import{_ as l,W as o,s as d,u as r,ah as p,I as t,w as s,Z as e,A as i}from"./chunks/framework.ChbOY6p5.js";import"./chunks/theme.B6FFP-dx.js";const x=JSON.parse('{"title":"我在 Linux 中使用的 5 个 Git 配置 | LCTT x X-CMD","titleTemplate":false,"description":"我在 Linux 中使用的 5 个 Git 配置 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"我在 Linux 中使用的 5 个 Git 配置 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我在 Linux 中使用的 5 个 Git 配置 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20220922 5 Git configurations I make on Linux","title":"我在 Linux 中使用的 5 个 Git 配置","tag":"202210"},"relativePath":"202210/20220922 5 Git configurations I make on Linux.md","filePath":"[post].md"}'),c={name:"202210/20220922 5 Git configurations I make on Linux.md"};function u(g,a,h,m,b,v){const n=o("Link");return r(),d("div",null,[a[29]||(a[29]=p(`<h1 id="我在-linux-中使用的-5-个-git-配置" tabindex="-1">我在 Linux 中使用的 5 个 Git 配置 <a class="header-anchor" href="#我在-linux-中使用的-5-个-git-配置" aria-label="Permalink to 我在 Linux 中使用的 5 个 Git 配置">​</a></h1><blockquote><p>这份简要指南能够帮助你快速开始使用 Git，以及配置一些选项。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202210/11/162338c314ls57bg51hd45.jpg" alt=""></p><p>在 Linux 中设置 Git 十分简单，但为了获得完美的配置，我做了以下五件事：</p><ol><li>创建全局配置</li><li>设置默认名称</li><li>设置默认邮箱地址</li><li>设置默认分支名称</li><li>设置默认编辑器</li></ol><p>我使用 Git 管理我的代码、命令行脚本以及文档版本。这意味着每次我开始一项新的任务，首先我需要创建一个文件目录并将其添加到 Git 库中：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ mkdir newproject</span></span>
<span class="line"><span>$ cd newproject</span></span>
<span class="line"><span>$ git init</span></span></code></pre></div><p>有一些我一直想要的常规设置。不多，但可以避免我每次都进行配置。我喜欢利用 Git 的 <em>全局</em> 配置功能。</p><p>Git 提供了进行手动配置的 <code>git config</code> 命令，但这有一些注意事项。例如，通常你会设置邮箱地址。你可以通过运行 <code>git config user.email 你的邮件地址</code> 命令进行设置。然而，这只会在你当前所在的 Git 目录下起作用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git config user.email alan@opensource.com</span></span>
<span class="line"><span>fatal: not in a git directory</span></span></code></pre></div><p>此外，当这个命令在 Git 仓库中运行时，它只会配置特定的一个仓库。在新的仓库中，你不得不重复这个步骤。我可以通过全局配置来避免重复。选项 <code>--global</code> 会指示 Git 将邮箱地址写入全局配置 <code>~/.gitconfig</code> 文件中，甚至在必要时会创建它：</p><blockquote><p>请记住，波浪线（<code>~</code>）代表你的主文件夹。在我的电脑中它是 <code>/home/alan</code>。</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git config --global user.email alan@opensource.com</span></span>
<span class="line"><span>$ cat ~/.gitconfig</span></span>
<span class="line"><span>[user]</span></span>
<span class="line"><span>        email = alan@opensource.com</span></span></code></pre></div><p>这里的缺点是，如果你有大量偏好设置，需要输入很多命令，这将花费大量时间并且很容易出错。Git 提供了更加快捷有效的方式，可以直接编辑你的全局配置文件——这是我列表中的第一项！</p><h3 id="_1、创建全局配置" tabindex="-1">1、创建全局配置 <a class="header-anchor" href="#_1、创建全局配置" aria-label="Permalink to 1、创建全局配置">​</a></h3><p>如果你刚开始使用 Git，或许你还没有该文件。不用担心，让我们直接开始。只需要用 <code>--edit</code> 选项：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git config --global --edit</span></span></code></pre></div><p>如果没有该文件，Git 将会创建一个包含以下内容的新文件，并使用你终端的默认编辑器打开它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># This is Git&#39;s per-user configuration file.</span></span>
<span class="line"><span>[user]</span></span>
<span class="line"><span># Please adapt and uncomment the following lines:</span></span>
<span class="line"><span>#       name = Alan</span></span>
<span class="line"><span>#       email = alan@hopper</span></span>
<span class="line"><span>~</span></span>
<span class="line"><span>~</span></span>
<span class="line"><span>~</span></span>
<span class="line"><span>&quot;~/.gitconfig&quot; 5L, 155B                                     1,1           All</span></span></code></pre></div><p>现在我们已经打开了编辑器，并且 Git 已经在后台创建了全局配置文件，我们可以继续接下来的设置。</p><h3 id="_2、设置默认名称" tabindex="-1">2、设置默认名称 <a class="header-anchor" href="#_2、设置默认名称" aria-label="Permalink to 2、设置默认名称">​</a></h3><p>名字是该文件中的首要条目，让我们先从它开始。用命令行设置我的名称是 <code>git config --global user.name &quot;Alan Formy-Duval&quot;</code>。不用在命令行中运行该命令，只需要在配置文件中编辑 <code>name</code> 条目就行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>name = Alan Formy-Duval</span></span></code></pre></div><h3 id="_3、设置默认邮箱地址" tabindex="-1">3、设置默认邮箱地址 <a class="header-anchor" href="#_3、设置默认邮箱地址" aria-label="Permalink to 3、设置默认邮箱地址">​</a></h3><p>邮箱地址是第二个条目，让我们添加它。默认情况下，Git 使用你的系统提供的名称和邮箱地址。如果不正确或者你想要更改，你可以在配置文件中具体说明。事实上，如果你没有配置这些，Git 在你第一次提交时会友好的提示你：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Committer: Alan &lt;alan@hopper&gt;</span></span>
<span class="line"><span>Your name and email address were configured automatically based</span></span>
<span class="line"><span>on your username and hostname. Please check that they are accurate....</span></span></code></pre></div><p>在命令行中运行 <code>git config --global user.email &quot;alan@opensource.com&quot;</code> 会设置好我的邮箱。同样，我们在配置文件中编辑 <code>email</code> 条目，提供你的邮箱地址：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>email = alan@opensource.com</span></span></code></pre></div><p>我喜欢设置的最后两个设置是默认分支名称和默认编辑器。当你仍在编辑器中时，需要添加这些指令。</p><h3 id="_4、设置默认分支名称" tabindex="-1">4、设置默认分支名称 <a class="header-anchor" href="#_4、设置默认分支名称" aria-label="Permalink to 4、设置默认分支名称">​</a></h3><p>目前有一种趋势，即不再使用 <code>master</code> 作为默认分支名称。事实上，在新存储库初始化时，Git 将通过友好的消息提示更改默认分支名称：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git init</span></span>
<span class="line"><span>hint: Using &#39;master&#39; as the name for the initial branch. This default branch name</span></span>
<span class="line"><span>hint: is subject to change. To configure the initial branch name to use in all</span></span>
<span class="line"><span>hint: of your new repositories, which will suppress this warning, call:</span></span>
<span class="line"><span>hint:</span></span>
<span class="line"><span>hint:   git config --global init.defaultBranch &lt;name&gt;</span></span></code></pre></div><p>这个名为 <code>defaultBranch</code> 的指令需要位于一个名为 <code>init</code> 的新部分中。现在普遍接受的是，许多程序员使用 <code>main</code> 这个词作为他们的默认分支。这是我喜欢使用的。将此部分后跟指令添加到配置中：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[init]</span></span>
<span class="line"><span>            defaultBranch = main</span></span></code></pre></div><h3 id="_5、设置默认编辑器" tabindex="-1">5、设置默认编辑器 <a class="header-anchor" href="#_5、设置默认编辑器" aria-label="Permalink to 5、设置默认编辑器">​</a></h3>`,35)),t("p",null,[a[3]||(a[3]=s("第五个设置是设置默认的编辑器。这是指 Git 将使用的编辑器，用于在你每次将更改提交到存储库时输入你的提交消息。不论是 ")),e(n,{href:"https://opensource.com/article/20/12/gnu-nano"},{default:i(()=>a[0]||(a[0]=[s("nano")])),_:1}),a[4]||(a[4]=s("、")),e(n,{href:"https://opensource.com/resources/what-emacs"},{default:i(()=>a[1]||(a[1]=[s("emacs")])),_:1}),a[5]||(a[5]=s("、")),e(n,{href:"https://opensource.com/article/19/3/getting-started-vim"},{default:i(()=>a[2]||(a[2]=[s("vi")])),_:1}),a[6]||(a[6]=s(" 还是其他编辑器，每个人都有他喜欢的。我喜欢用 vi。添加 ")),a[7]||(a[7]=t("code",null,"core",-1)),a[8]||(a[8]=s(" 部分，并设置 ")),a[9]||(a[9]=t("code",null,"editor",-1)),a[10]||(a[10]=s(" 指令为你喜欢的编辑器。"))]),a[30]||(a[30]=p(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[core]</span></span>
<span class="line"><span>            editor = vi</span></span></code></pre></div>`,1)),t("p",null,[a[12]||(a[12]=s("这是最后一项。退出编辑器。Git 在主目录下保存全局配置文件。如果你再次运行编辑命令，将会看到所有内容。注意配置文件是明文存储的文本文件，因此它可以很容易使用文本工具查看，如 ")),e(n,{href:"https://opensource.com/article/19/2/getting-started-cat-command"},{default:i(()=>a[11]||(a[11]=[s("cat")])),_:1}),a[13]||(a[13]=s(" 命令。这是我的配置文件内容："))]),a[31]||(a[31]=p(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cat ~/.gitconfig</span></span>
<span class="line"><span>[user]</span></span>
<span class="line"><span>        email = alan@opensource.com</span></span>
<span class="line"><span>        name = Alan Formy-Duval</span></span>
<span class="line"><span>[core]</span></span>
<span class="line"><span>        editor = vi</span></span>
<span class="line"><span>[init]</span></span>
<span class="line"><span>        defaultBranch = main</span></span></code></pre></div><p>这是一个简单的指南，可以让你快速开始使用 Git 和它的一些配置选项。</p><hr>`,3)),t("p",null,[a[15]||(a[15]=s("via: ")),e(n,{href:"https://opensource.com/article/22/9/git-configuration-linux"},{default:i(()=>a[14]||(a[14]=[s("https://opensource.com/article/22/9/git-configuration-linux")])),_:1})]),t("p",null,[a[20]||(a[20]=s("作者：")),e(n,{href:"https://opensource.com/users/alanfdoss"},{default:i(()=>a[16]||(a[16]=[s("Alan Formy-Duval")])),_:1}),a[21]||(a[21]=s(" 选题：")),e(n,{href:"https://github.com/lkxed"},{default:i(()=>a[17]||(a[17]=[s("lkxed")])),_:1}),a[22]||(a[22]=s(" 译者：")),e(n,{href:"https://github.com/Donkey-Hao"},{default:i(()=>a[18]||(a[18]=[s("Donkey-Hao")])),_:1}),a[23]||(a[23]=s(" 校对：")),e(n,{href:"https://github.com/wxy"},{default:i(()=>a[19]||(a[19]=[s("wxy")])),_:1})]),t("p",null,[a[26]||(a[26]=s("本文由 ")),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>a[24]||(a[24]=[s("LCTT")])),_:1}),a[27]||(a[27]=s(" 原创编译，")),e(n,{href:"https://linux.cn/"},{default:i(()=>a[25]||(a[25]=[s("Linux中国")])),_:1}),a[28]||(a[28]=s(" 荣誉推出"))])])}const C=l(c,[["render",u]]);export{x as __pageData,C as default};
